from typing import List, Tuple

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    sum_result = sum(numbers)
    product_result = 1
    for number in numbers:
        product_result *= number
    return (sum_result, product_result)

from typing import List, Any

def filter_integers(values: List[Any]) -> List[int]:
    return [value for value in values if isinstance(value, int)]

def correct_bracketing(brackets: str):
    balance = 0
    for char in brackets:
        if char == '(':  
            balance += 1
        elif char == ')':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def vowels_count(s):
    vowels = 'aeiouAEIOU'
    count = 0
    for i in range(len(s)):
        if s[i] in vowels:
            count += 1
        elif s[i] == 'y' or s[i] == 'Y':
            if i == len(s) - 1:
                count += 1
    return count

def anti_shuffle(s):
    result = []
    words = s.split(' ')
    for word in words:
        sorted_word = ''.join(sorted(word, key=lambda c: (c.isalpha(), c)))
        result.append(sorted_word)
    return ' '.join(result)

def next_smallest(lst):
    unique_values = list(set(lst))
    if len(unique_values) < 2:
        return None
    unique_values.sort()
    return unique_values[1]

def minPath(grid, k):
    from heapq import heappop, heappush
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    min_path = None

    # Priority queue to explore paths
    pq = []
    for i in range(N):
        for j in range(N):
            heappush(pq, (grid[i][j], [(grid[i][j])], (i, j)))  # (current_value, path_so_far, position)

    while pq:
        current_value, path_so_far, (x, y) = heappop(pq)
        if len(path_so_far) == k:
            if min_path is None or path_so_far < min_path:
                min_path = path_so_far
            continue
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                heappush(pq, (grid[nx][ny], path_so_far + [grid[nx][ny]], (nx, ny)))

    return min_path

def is_equal_to_sum_even(n):
    """Evaluate whether the given number n can be written as the sum of exactly 4 positive even numbers"""
    return n >= 8 and n % 2 == 0

def sum_squares(lst):
    total = 0
    for i, value in enumerate(lst):
        if i % 3 == 0:
            total += value ** 2
        elif i % 4 == 0:
            total += value ** 3
        else:
            total += value
    return total

def x_or_y(n, x, y):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True
    return x if is_prime(n) else y

def even_odd_count(num):
    even_count = 0
    odd_count = 0
    for digit in str(abs(num)):
        if int(digit) % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
    return (even_count, odd_count)

import hashlib

def string_to_md5(text):
    if text == '':
        return None
    return hashlib.md5(text.encode()).hexdigest()
